echo '' | base64 -d > /tmp/kret.pl; docker cp /tmp/kret.pl koha-test:/tmp/kret.pl; docker exec koha-test chmod 644 /tmp/kret.pl
docker exec koha-test koha-shell kohadent -c "perl /tmp/kret.pl" 2>&1 | grep -v "^\s*'" | head -20
docker exec koha-test koha-mysql kohadent -e "select issue_id, itemnumber, borrowernumber, date_due, issuedate, branchcode, renewals_count from issues; select itemnumber, barcode, onloan, homebranch, holdingbranch from items where barcode='LIB000002'; select * from old_issues limit 2;"
